const ROOM_ORDER = ['Living Room', 'Bedroom', 'Kitchen', 'Bathroom', 'Dining', 'Home Office'];

/**
 * Attach each theme's own photography. Room inspiration is derived from the room tag on
 * each photo, so a room tab only exists when the theme really has photos of that room.
 */
export const THEMES: Theme[] = RAW_THEMES.map((t) => {
  const im = THEME_IMAGES[t.slug];
  if (!im) return t;
  const rooms = ROOM_ORDER
    .map((room) => ({ room, images: im.gallery.filter((g) => g.room === room).map((g) => photoUrl(g.id, 700)) }))
    .filter((r) => r.images.length > 0);
  return {
    ...t,
    coverImage: photoUrl(im.cover, 900),
    galleryImages: im.gallery.map((g) => photoUrl(g.id, 900)),
    rooms,
    roomCount: rooms.length,
  };
});

