export function getThemeBySlug(slug: string): Theme | undefined {
  return THEMES.find(t => t.slug === slug);
}

export function getThemesByCollection(collectionId: string): Theme[] {
  return THEMES.filter(t => t.collections.includes(collectionId));
}

export function searchThemes(query: string): Theme[] {
  if (!query.trim()) return THEMES;
  const q = query.toLowerCase();
  return THEMES.filter(t =>
    t.name.toLowerCase().includes(q) ||
    t.tagline.toLowerCase().includes(q) ||
    t.description.toLowerCase().includes(q) ||
    t.tags.some(tag => tag.toLowerCase().includes(q)) ||
    t.materials.some(m => m.toLowerCase().includes(q)) ||
    t.furniture.some(f => f.toLowerCase().includes(q)) ||
    t.colors.some(c => c.name.toLowerCase().includes(q)) ||
    t.category.toLowerCase().includes(q)
  );
}

export function getSimilarThemes(slug: string): Theme[] {
  const theme = getThemeBySlug(slug);
  if (!theme) return [];
  return theme.similarThemes
    .map(s => getThemeBySlug(s))
    .filter((t): t is Theme => t !== undefined);
}
